arguments.command:
cat > src/CheckoutPricing.Application/Checkout.cs <<'E'
namespace CheckoutPricing.Application;

public enum CustomerTier { Standard, Gold }

public static class Checkout
{
    public static decimal CalculatePayableTotal(CustomerTier tier, decimal subtotal) =>
        throw new NotImplementedException("Loyalty discount is not implemented.");
}
E
cat > tests/CheckoutPricing.UnitTests/GoldDiscountTests.cs <<'E'
using CheckoutPricing.Application;

namespace CheckoutPricing.UnitTests;

public class GoldDiscountTests
{
    [Fact]
    public void Gold_customer_with_100_subtotal_pays_95()
    {
        Assert.Equal(95.00m, Checkout.CalculatePayableTotal(CustomerTier.Gold, 100.00m));
    }
}
E
dotnet test tests/CheckoutPricing.UnitTests 2>&1 | grep -v warning | tail -20

